  function update(dt){elapsed+=dt;attackTimer=Math.max(0,attackTimer-dt);dodgeTimer=Math.max(0,dodgeTimer-dt);castTimer=Math.max(0,castTimer-dt);invuln=Math.max(0,invuln-dt);player.hit=Math.max(0,player.hit-dt);if(lastToast>0&&(lastToast-=dt)<=0)ui.toast.classList.remove('show');
