  function render(){ctx.clearRect(0,0,W,H);const shake=screenShake?rand(-screenShake,screenShake):0;ctx.save();ctx.translate(shake,shake*.6);drawWorld();ctx.restore();}
  function drawWorld(){
    const bg=ctx.createLinearGradient(0,0,W,H);bg.addColorStop(0,'#1c2727');bg.addColorStop(.52,'#202725');bg.addColorStop(1,'#11191a');ctx.fillStyle=bg;ctx.fillRect(0,0,W,H);
    // Ashen flagstone, subtly varied in a quiet grid.
    for(let y=0;y<H;y+=46)for(let x=0;x<W;x+=57){let n=((Math.floor(x/57)*13+Math.floor(y/46)*29)%11)/100;ctx.fillStyle=`rgba(${100+Math.floor(n*100)},${112+Math.floor(n*90)},${101+Math.floor(n*70)},.12)`;ctx.fillRect(x+1,y+1,55,44);ctx.strokeStyle='rgba(8,13,13,.27)';ctx.lineWidth=1;ctx.strokeRect(x+.5,y+.5,56,45);}
    // Sanctum's circular inlaid arena.
    ctx.save();ctx.translate(W/2,H*.53);let radius=Math.min(W*.39,H*.39);ctx.strokeStyle='rgba(187,157,112,.14)';ctx.lineWidth=2;for(let r of [radius,radius*.92,radius*.67]){ctx.beginPath();ctx.ellipse(0,0,r,r*.75,0,0,Math.PI*2);ctx.stroke();}for(let a=0;a<12;a++){let angle=a*Math.PI/6;ctx.beginPath();ctx.moveTo(Math.cos(angle)*radius,Math.sin(angle)*radius*.75);ctx.lineTo(Math.cos(angle)*radius*.93,Math.sin(angle)*radius*.7);ctx.stroke();}ctx.restore();
    // Old pillars, rubble, scattered ash stones.
    for(const p of props){if(p.type<.2)drawPillar(p.x,p.y,p.r);else if(p.type<.45){ctx.fillStyle='#313736';ctx.beginPath();ctx.ellipse(p.x,p.y,p.r*1.25,p.r*.65,-.3,0,Math.PI*2);ctx.fill();ctx.strokeStyle='#4b504a';ctx.stroke();}else{ctx.fillStyle=`rgba(190,177,150,${.12+p.type*.13})`;ctx.beginPath();ctx.arc(p.x,p.y,p.r*.35,0,Math.PI*2);ctx.fill();}}
    // Ember braziers along the perimeter
    for(const x of [W*.12,W*.88]){const y=H*.34;drawBrazier(x,y);}
    stones.forEach((s,i)=>drawStone(s,i));
    if(boss.active&&boss.hp>0)drawBoss();
    projectiles.forEach(drawProjectile);
    particles.forEach(p=>{ctx.globalAlpha=clamp(p.life/p.max,0,1);ctx.fillStyle=p.color;ctx.shadowColor=p.color;ctx.shadowBlur=12;ctx.beginPath();ctx.arc(p.x,p.y,p.size,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.globalAlpha=1;});
    drawPlayer();
    drawAsh();
  }
  function drawPillar(x,y,r){ctx.save();ctx.translate(x,y);ctx.fillStyle='rgba(0,0,0,.24)';ctx.beginPath();ctx.ellipse(4,r*.35,r*1.5,r*.7,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#333a37';ctx.fillRect(-r*.56,-r*.9,r*1.12,r*1.7);ctx.fillStyle='#4b5048';ctx.fillRect(-r*.8,-r,r*1.6,r*.27);ctx.fillRect(-r*.75,r*.64,r*1.5,r*.28);ctx.fillStyle='#606052';ctx.fillRect(-r*.35,-r*.82,r*.18,r*1.35);ctx.strokeStyle='#252d2b';ctx.strokeRect(-r*.56,-r*.9,r*1.12,r*1.7);ctx.restore();}
  function drawBrazier(x,y){const glow=ctx.createRadialGradient(x,y-8,1,x,y,42);glow.addColorStop(0,'rgba(246,164,72,.25)');glow.addColorStop(1,'rgba(246,164,72,0)');ctx.fillStyle=glow;ctx.fillRect(x-45,y-55,90,90);ctx.fillStyle='#353a36';ctx.fillRect(x-7,y-4,14,30);ctx.fillStyle='#626051';ctx.fillRect(x-14,y-7,28,6);ctx.fillStyle='#f0a94f';ctx.shadowColor='#ef8b38';ctx.shadowBlur=17;ctx.beginPath();ctx.moveTo(x,y-33-Math.sin(elapsed*4+x)*3);ctx.quadraticCurveTo(x+14,y-13,x,y-8);ctx.quadraticCurveTo(x-12,y-17,x,y-33);ctx.fill();ctx.shadowBlur=0;}
  function drawStone(s,i){const pulse=.5+.5*Math.sin(elapsed*2+s.pulse);const glow=ctx.createRadialGradient(s.x,s.y,5,s.x,s.y,60);glow.addColorStop(0,s.lit?`rgba(238,179,93,${.22+pulse*.1})`:'rgba(214,157,79,.09)');glow.addColorStop(1,'rgba(214,157,79,0)');ctx.fillStyle=glow;ctx.fillRect(s.x-65,s.y-65,130,130);ctx.save();ctx.translate(s.x,s.y);ctx.fillStyle='rgba(0,0,0,.38)';ctx.beginPath();ctx.ellipse(0,14,31,13,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#343b36';ctx.beginPath();ctx.moveTo(-20,10);ctx.lineTo(-16,-28);ctx.lineTo(-8,-39);ctx.lineTo(13,-35);ctx.lineTo(20,8);ctx.closePath();ctx.fill();ctx.strokeStyle=s.lit?'#e7b66c':'#77705c';ctx.lineWidth=2;ctx.stroke();ctx.fillStyle=s.lit?'#ffc76e':'#8c815f';ctx.font=`${20+pulse*2}px Cinzel`;ctx.textAlign='center';ctx.textBaseline='middle';ctx.shadowColor=s.lit?'#ffb54d':'transparent';ctx.shadowBlur=s.lit?18:0;ctx.fillText(['ᚱ','ᛟ','ᚷ'][i],0,-11);ctx.shadowBlur=0;ctx.restore();if(!s.lit){ctx.fillStyle='rgba(232,212,176,.65)';ctx.font='9px Cinzel';ctx.textAlign='center';ctx.fillText('WARDSTONE',s.x,s.y+31);}}
  function drawPlayer(){let p=player;ctx.save();ctx.translate(p.x,p.y);if(invuln>0&&Math.floor(elapsed*18)%2===0)ctx.globalAlpha=.48;const bob=p.walk?Math.sin(p.walk*2)*2:Math.sin(elapsed*2)*.7;ctx.fillStyle='rgba(0,0,0,.42)';ctx.beginPath();ctx.ellipse(0,12,17,8,0,0,Math.PI*2);ctx.fill();ctx.translate(0,bob);ctx.fillStyle='#554c40';ctx.beginPath();ctx.moveTo(-10,-5);ctx.lineTo(-12,10);ctx.lineTo(0,15);ctx.lineTo(12,9);ctx.lineTo(8,-7);ctx.closePath();ctx.fill();ctx.fillStyle='#b8a78a';ctx.beginPath();ctx.ellipse(0,-12,8,10,0,0,Math.PI*2);ctx.fill();ctx.fillStyle='#282d2a';ctx.beginPath();ctx.arc(0,-15,8.5,Math.PI,0);ctx.lineTo(7,-12);ctx.lineTo(-7,-12);ctx.fill();ctx.strokeStyle='#d5bc8e';ctx.lineWidth=2.2;ctx.beginPath();ctx.moveTo(p.faceX*11,p.faceY*11);ctx.lineTo(p.faceX*27,p.faceY*27);ctx.stroke();ctx.strokeStyle='#49392a';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(p.faceX*10,p.faceY*10);ctx.lineTo(p.faceX*18,p.faceY*18);ctx.stroke();if(p.hit>0){ctx.strokeStyle='rgba(246,215,155,.75)';ctx.lineWidth=3;ctx.beginPath();ctx.arc(0,-3,31,-1.7,1.2);ctx.stroke();}ctx.restore();}
  function drawBoss(){let b=boss;ctx.save();ctx.translate(b.x,b.y);const wind=b.windup>0?Math.sin(elapsed*27)*4:Math.sin(b.anim*3)*1.5;const glow=ctx.createRadialGradient(0,4,8,0,4,75);glow.addColorStop(0,'rgba(210,81,51,.23)');glow.addColorStop(1,'rgba(210,81,51,0)');ctx.fillStyle=glow;ctx.fillRect(-80,-80,160,160);ctx.fillStyle='rgba(0,0,0,.5)';ctx.beginPath();ctx.ellipse(0,20,37,15,0,0,Math.PI*2);ctx.fill();ctx.translate(0,wind);ctx.fillStyle='#292c29';ctx.beginPath();ctx.moveTo(-24,10);ctx.lineTo(-30,-25);ctx.lineTo(-22,-45);ctx.lineTo(-14,-38);ctx.lineTo(-6,-55);ctx.lineTo(0,-40);ctx.lineTo(13,-54);ctx.lineTo(16,-36);ctx.lineTo(28,-31);ctx.lineTo(25,11);ctx.closePath();ctx.fill();ctx.strokeStyle='#514940';ctx.lineWidth=2;ctx.stroke();ctx.fillStyle='#bf6447';ctx.shadowColor='#ed7444';ctx.shadowBlur=15;ctx.beginPath();ctx.arc(-9,-25,3,0,Math.PI*2);ctx.arc(9,-25,3,0,Math.PI*2);ctx.fill();ctx.shadowBlur=0;ctx.strokeStyle='#a95a43';ctx.lineWidth=4;ctx.beginPath();ctx.moveTo(-24,-31);ctx.lineTo(-41,-50);ctx.lineTo(-49,-29);ctx.moveTo(24,-31);ctx.lineTo(42,-52);ctx.lineTo(48,-29);ctx.stroke();ctx.restore();}
  function drawProjectile(p){ctx.save();ctx.fillStyle=p.team==='boss'?'#f07850':'#ffd078';ctx.shadowColor=ctx.fillStyle;ctx.shadowBlur=18;ctx.beginPath();ctx.arc(p.x,p.y,p.r,0,Math.PI*2);ctx.fill();ctx.globalAlpha=.35;ctx.beginPath();ctx.arc(p.x-p.vx*.035,p.y-p.vy*.035,p.r*1.8,0,Math.PI*2);ctx.fill();ctx.restore();}
  function drawAsh(){for(let i=0;i<28;i++){let x=(i*167+elapsed*(8+i%4)*((i%2)?1:-1))%W;let y=(i*97+Math.sin(elapsed*.6+i)*22+H)%H;ctx.fillStyle=`rgba(218,202,170,${.08+(i%5)*.025})`;ctx.beginPath();ctx.arc(x,y,1+(i%3)*.35,0,Math.PI*2);ctx.fill();}}
  function frame(now){requestAnimationFrame(frame);let dt=Math.min(.035,(now-last)/1000||0);last=now;if(running&&!paused&&!ended){update(dt);const s=stoneNearest();const nearBoss=boss.active&&dist(player,boss)<82;ui.prompt.textContent=s?'[ E ]  ATTUNE TO WARDSTONE':nearBoss?'[ E ]  CLAIM A SPARK':'';ui.prompt.classList.toggle('show',!!s||nearBoss);}render();}
  $('start-button').addEventListener('click',start);$('resume-button').addEventListener('click',togglePause);$('pause-button').addEventListener('click',togglePause);$('restart-button').addEventListener('click',()=>{reset();ui.end.classList.add('hidden');ui.title.classList.remove('hidden');running=false;});setupTouch();window.addEventListener('resize',resize);resize();reset();requestAnimationFrame(frame);
})();

